// Process and deduplicate horror content from multiple sources
const crypto = require('crypto');
const items = $input.all();
const horrorContent = [];
const seenHashes = new Set();

for (const item of items) {
  const title = item.json.title || 'Untitled Horror Content';
  const link = item.json.link || item.json.guid || '';

  // Create content hash for deduplication
  const contentHash = crypto
    .createHash('md5')
    .update(title + link)
    .digest('hex');

  // Skip duplicates
  if (seenHashes.has(contentHash)) {
    continue;
  }
  seenHashes.add(contentHash);

  const content = {
    idempotencyKey: `multi-${contentHash}`,
    title: title,
    link: link,
    description: item.json.contentSnippet || item.json.description || '',
    pubDate: item.json.pubDate || new Date().toISOString(),
    categories: item.json.categories || ['horror'],
    source: extractSource(link),
    horrorTags: generateHorrorTags(title),
    engagementScore: calculateEngagementScore(item.json),
    contentHash: contentHash
  };
  horrorContent.push(content);
}

return horrorContent.map(item => ({ json: item }));

function extractSource(link) {
  if (link.includes('bloody-disgusting')) return 'Bloody Disgusting';
  if (link.includes('dreadcentral')) return 'Dread Central';
  if (link.includes('horrornews.net')) return 'Horror News Net';
  if (link.includes('fangoria')) return 'Fangoria';
  return 'Unknown Source';
}

function generateHorrorTags(title) {
  const horrorKeywords = [
    'horror', 'scary', 'terror', 'nightmare', 'creepy',
    'paranormal', 'supernatural', 'slasher', 'thriller',
    'ghost', 'vampire', 'zombie', 'monster', 'dark'
  ];

  const tags = ['horror'];
  const titleLower = title.toLowerCase();

  for (const keyword of horrorKeywords) {
    if (titleLower.includes(keyword) && !tags.includes(keyword)) {
      tags.push(keyword);
    }
  }

  return tags.slice(0, 5);
}

function calculateEngagementScore(item) {
  let score = 50;

  const highEngagementKeywords = ['exclusive', 'trailer', 'preview', 'new', 'breaking', 'review'];
  const title = (item.title || '').toLowerCase();

  for (const keyword of highEngagementKeywords) {
    if (title.includes(keyword)) {
      score += 10;
    }
  }

  return Math.min(score, 100);
}

// Select best content from filtered items
const items = $input.all();

// Sort by engagement score and source diversity
const sorted = items.sort((a, b) => b.json.engagementScore - a.json.engagementScore);

// Select top 3 items from different sources when possible
const selected = [];
const usedSources = new Set();

for (const item of sorted) {
  if (selected.length >= 3) break;

  if (!usedSources.has(item.json.source)) {
    selected.push(item);
    usedSources.add(item.json.source);
  }
}

return selected;

// Prepare YouTube data with source tracking
const aiResponse = $input.first().json;
const originalContent = $input.first().json;
let parsedContent;

try {
  parsedContent = typeof aiResponse.message === 'string' 
    ? JSON.parse(aiResponse.message) 
    : aiResponse.message;
} catch (error) {
  parsedContent = {
    title: originalContent.title,
    description: `From ${originalContent.source}: ${originalContent.description}`,
    tags: originalContent.horrorTags,
    categoryId: 1
  };
}

const horrorData = {
  idempotencyKey: originalContent.idempotencyKey,
  snippet: {
    title: parsedContent.title,
    description: parsedContent.description,
    categoryId: parsedContent.categoryId || 1,
    tags: parsedContent.tags || originalContent.horrorTags,
    defaultLanguage: 'en',
    defaultAudioLanguage: 'en'
  },
  status: {
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  },
  contentDetails: {
    caption: 'true'
  },
  metadata: {
    uploadDate: new Date().toISOString(),
    horrorGenre: true,
    contentRating: 'mature',
    originalLink: originalContent.link,
    source: originalContent.source,
    engagementScore: originalContent.engagementScore,
    multiSource: true
  }
};

return { json: horrorData };

